import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addWeeks_TriageGen2Test {

    @Test
    public void testAddWeeks_PositiveValue() {
        // Arrange: Set a specific date (2023-10-01 is a Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 10, 1, 0, 0, 0, 0);
        long originalMillis = dt.getMillis();
        int weeksToAdd = 2;

        // Act
        dt.addWeeks(weeksToAdd);

        // Assert: 2 weeks after Oct 1 is Oct 15
        assertEquals(2023, dt.getYear());
        assertEquals(10, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
        assertNotEquals(originalMillis, dt.getMillis());
    }








}

